function [speed_signals, voltage_signals, current_signals] = mfun_olvhz_monitored_signals(fbk_in, ref_in, w_M_ref, p)
%MFUN_OLVHZ_MONITORED_SIGNALS Block Monitored signals of the control system.
%   Generated by motulator_export from the MATLAB port of motulator; the MATLAB Function
%   block of a model calls this function, copied into the folder of the model. The
%   parameters are the fields of the struct p, the struct of the block in the struct
%   ctrl_par of the parameters of the blocks of its control system (e.g.,
%   ctrl_par.SpeedController, see the function of the parameters of the control system,
%   e.g., fvc_params; [] as NaN).
fbk = im_open_loop_vhz_feedbacks_unpack(fbk_in);
ref = im_open_loop_vhz_references_unpack(ref_in);
% Monitored signals
speed_signals = [w_M_ref; fbk.w_s];
voltage_signals = [abs(ref.u_s); abs(fbk.u_s)];
current_signals = [real(fbk.i_s); imag(fbk.i_s)];
end

function s = im_open_loop_vhz_feedbacks_unpack(u)
%IM_OPEN_LOOP_VHZ_FEEDBACKS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_s', complex(u(1), u(2)), ...
    'u_s', complex(u(3), u(4)), ...
    'u_s_zoh', complex(u(5), u(6)), ...
    'w_M', u(7), ...
    'w_s', u(8), ...
    'w_c', u(9), ...
    'theta_c', u(10));
end

function s = im_open_loop_vhz_references_unpack(u)
%IM_OPEN_LOOP_VHZ_REFERENCES_UNPACK Struct of the signal vector u.
s = struct( ...
    'u_s', complex(u(1), u(2)));
end
